// Üretilen dosya: tool/ozgun/uret.py. Biyoloji ve Yaşam Bilimleri · Bitki biyolojisi ayrıntıları: bitkisel dokular, hormonlar, ksilem-floem taşıması, stoma mekanizması, tropizma-nasti ve fotoperiyodizm (kolay).
const ozBiology15Kolay = <(String, String, List<String>, String)>[
  ('Sürgün ve kök uçlarındaki büyüme noktalarında konumlanarak bitkinin yaşamı boyunca boyca uzamasını sağlayan embriyonik kökenli doku hangisidir?', 'Uç (apikal) meristem dokusu', ['Mantar kambiyumu (fellogen) tabakası', 'Sekonder sklerenkima lif demetleri', 'Süberinleşmiş periderm örtü tabakası'], 'Apikal meristem kök ve gövde uçlarında bulunur, mitozla primer büyümeyi yani boyca uzamayı gerçekleştirir.'),
  ('Bölünür doku hücrelerinin sitoplazma yoğunluğu, koful büyüklüğü ve çeper kalınlığı bakımından olgun parankima hücrelerinden temel farkı nedir?', 'Bol sitoplazmalı, çok küçük kofullu ve ince selüloz çeperli olmaları', ['Kalın ligninleşmiş ikincil çeper ve geniş merkezi koful taşımaları', 'Çekirdeklerini kaybederek metabolik etkinliklerini tamamen durdurmaları', 'Hücre aralarında geniş havalandırma boşlukları ve süberin biriktirmeleri'], 'Meristem hücreleri sürekli mitoz geçirdiği için büyük çekirdekli, bol sitoplazmalı, ince çeperli ve kofulları yok denecek kadar küçüktür.'),
  ('Bölünme yeteneğini yitirmiş canlı parankima hücrelerinin hormonların etkisiyle yeniden mitoz geçirme özelliği kazanması sonucunda hangi doku oluşur?', 'İkincil (sekonder) meristem', ['Birincil (primer) uç meristem', 'Ölü taş hücreli sklerenkima', 'Kütin kaplı üst epidermis'], 'Farklılaşmış canlı hücrelerin sonradan bölünme yeteneği kazanmasıyla vasküler kambiyum ve mantar kambiyumu gibi sekonder meristemler gelişir.'),
  ('Bir ormancı kesilmiş bir çam kütüğünde birbirini izleyen bir açık ve bir koyu halkayı birlikte saydığında doğrudan neyi belirlemiş olur?', 'Ağacın geçirdiği büyüme mevsimi sayısını ve yaklaşık yaşını', ['Kök sisteminin toprağın kaç metre derinliğine indiğini', 'Ağacın yaşamı boyunca ürettiği toplam kozalak miktarını', 'Yapraklardaki stoma sayısının epidermis hücrelerine oranını'], 'Bir yıllık büyüme periyodunda oluşan bir açık (ilkbahar) ve bir koyu (yaz/sonbahar) halka birlikte bir yaş halkasını temsil eder.'),
